{
  "schema_version": "text2ifc/design-brief/2.0",
  "language": "zh-CN",
  "original_request": "创建一个两层住宅，但我还不知道楼梯位置、墙厚、楼板厚度和门窗尺寸。",
  "status": "needs_clarification",
  "known_facts": {
    "building": {
      "number_of_storeys": 2
    },
    "walls": {
      "thickness_mm": 200
    },
    "slabs": {
      "thickness_mm": 150
    }
  },
  "fact_sources": [
    {
      "path": "/known_facts/building/number_of_storeys",
      "source_turns": ["turn-user-001"],
      "evidence_refs": ["capability:IFC2X3:IfcBuildingStorey"]
    },
    {
      "path": "/known_facts/walls/thickness_mm",
      "source_turns": ["turn-user-005"],
      "evidence_refs": ["capability:IFC2X3:IfcWall"]
    },
    {
      "path": "/known_facts/slabs/thickness_mm",
      "source_turns": ["turn-user-009"],
      "evidence_refs": ["capability:IFC2X3:IfcSlab"]
    }
  ],
  "missing_facts": [
    {
      "id": "mf-floor-dimensions",
      "code": "FLOOR_DIMENSIONS_MISSING",
      "path": "/known_facts/floors/dimensions",
      "message": "每层平面尺寸（长和宽）尚未确定。",
      "reason": "生成两层住宅需要每层的平面尺寸才能创建建筑楼层和空间。",
      "blocking": true,
      "evidence_refs": ["capability:IFC2X3:IfcBuildingStorey"],
      "source_turns": ["turn-user-001"]
    },
    {
      "id": "mf-floor-height",
      "code": "FLOOR_HEIGHT_MISSING",
      "path": "/known_facts/floors/height",
      "message": "层高尚未确定。",
      "reason": "生成楼层需要层高才能确定垂直尺寸。",
      "blocking": true,
      "evidence_refs": ["capability:IFC2X3:IfcBuildingStorey"],
      "source_turns": ["turn-user-001"]
    },
    {
      "id": "mf-stair-location",
      "code": "STAIR_LOCATION_MISSING",
      "path": "/known_facts/stairs/location",
      "message": "楼梯位置尚未确定。",
      "reason": "两层住宅需要楼梯连接楼层，位置未知无法生成楼梯。",
      "blocking": true,
      "evidence_refs": ["capability:IFC2X3:IfcStair"],
      "source_turns": ["turn-user-001"]
    },
    {
      "id": "mf-opening-details",
      "code": "OPENING_DETAILS_MISSING",
      "path": "/known_facts/openings",
      "message": "门窗的数量和尺寸尚未确定。",
      "reason": "用户未指定门窗数量和尺寸，无法生成洞口和门窗构件。",
      "blocking": true,
      "evidence_refs": ["capability:IFC2X3:IfcDoor", "capability:IFC2X3:IfcWindow"],
      "source_turns": ["turn-user-001"]
    }
  ],
  "ambiguities": [],
  "unsupported_requests": [],
  "user_corrections": [],
  "clarification_questions": [
    {
      "id": "q-floor-geometry",
      "text": "每层的平面尺寸（长和宽）和层高是多少？如果各层不同，请分别说明。",
      "targets": ["mf-floor-dimensions", "mf-floor-height"],
      "reason": "需要每层的几何尺寸才能创建建筑楼层。",
      "evidence_refs": ["capability:IFC2X3:IfcBuildingStorey"]
    },
    {
      "id": "q-stair-location",
      "text": "楼梯计划放在什么位置？请说明在平面中的大致位置（如靠近哪面墙或中心）。",
      "targets": ["mf-stair-location"],
      "reason": "需要楼梯位置才能生成楼梯构件。",
      "evidence_refs": ["capability:IFC2X3:IfcStair"]
    },
    {
      "id": "q-opening-details",
      "text": "门窗的尺寸和数量分别是多少？请分别说明每层门和窗的宽度、高度、窗台高（如有）以及数量。",
      "targets": ["mf-opening-details"],
      "reason": "需要门窗的详细规格才能生成洞口和门窗构件。",
      "evidence_refs": ["capability:IFC2X3:IfcDoor", "capability:IFC2X3:IfcWindow"]
    }
  ],
  "provenance": {
    "source_turns": ["turn-user-001", "turn-user-005", "turn-user-009"],
    "selected_evidence_ids": [
      "capability:IFC2X3:IfcBuildingStorey",
      "capability:IFC2X3:IfcWall",
      "capability:IFC2X3:IfcSlab",
      "capability:IFC2X3:IfcStair",
      "capability:IFC2X3:IfcDoor",
      "capability:IFC2X3:IfcWindow"
    ],
    "few_shot_ids": []
  }
}
